// Infection: a zombie's bite can carry it.
//
// A hit infects with INFECTION_CHANCE (a hash of the zombie and the tick, not
// the sim RNG, so combat doesn't shift everything else's randomness). The
// infection runs for INFECTION_TURN ticks (a day), half as fast for someone
// resting in an infirmary bed; then the survivor dies and gets up as a
// zombie. Medicine (crafted in a workshop) cures it: the infected fetch it
// like a bandage, and doctors bring it to infected patients (needs.ts, jobs.ts).
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Infection
{
    static Infection()
    {
        Time.onClock(() => INFECTION_TURN = 2 * Time.DAY_LENGTH);
    }

    public const double INFECTION_CHANCE = 0.03;

    public static double INFECTION_TURN = 2 * Time.DAY_LENGTH;

    /// <summary>What an infection does to mood while it lasts.</summary>
    public const double INFECTED_MOOD = -15;

    public static double roll(double a, double b)
    {
        var h = JsMath.imul(a ^ 668265263.0, 2246822507.0) ^ JsMath.imul(b, 3266489909.0);
        h = JsMath.imul(h ^ (Js.Ushr(h, 15)), 0x2c1b3c6d);
        return ((double)((Js.Ushr((h ^ (Js.Ushr(h, 13))), 0))) / (4294967296.0));
    }

    /// <summary>A zombie's hit: maybe it infects.</summary>
    public static void maybeInfect(SimState state, Survivor s, string zombieId, double chance = INFECTION_CHANCE)
    {
        if (s.infection != null)
        {
            return;
        }
        if (roll(Js.Num(zombieId.replace(/*TODO regex /\D/g*/null, "")), state.tick) >= chance)
        {
            return;
        }
        s.infection = 0;
        Events.logEvent(state, $"{Js.Str(s.name)} was bitten and is infected: medicine can cure it");
    }

    /// <summary>Runs every tick for every survivor. Returns a cause of death when the infection wins.</summary>
    public static string? updateInfection(SimState state, Survivor s)
    {
        if (s.infection == null)
        {
            return null;
        }
        if (!Js.T(Medicine.inInfirmary(state, s)) || ((state.tick % 2) == 0))
        {
            s.infection += 1;
        }
        return (s.infection >= INFECTION_TURN) ? "the infection" : null;
    }

    public static bool isInfected(Survivor s)
    {
        return s.infection != null;
    }
}
